/* global VARIANT */

import isHex from './is-hex.js';

// Prefer our implementation of decodeHex over Buffer when we don't know the VARIANT
// to avoid accidentally importing the Buffer shim in the browser.

// char code -> nibble value; 255 marks a non-hex character.
const NIBBLES = new Uint8Array(128).fill(255);
for (let i = 0; i < 10; i++) NIBBLES[48 + i] = i; // '0'-'9'
for (let i = 0; i < 6; i++) {
  NIBBLES[97 + i] = 10 + i; // 'a'-'f'
  NIBBLES[65 + i] = 10 + i; // 'A'-'F'
}

function decodeHex(hex) {
  if (typeof hex !== 'string') throw new Error('not a string');

  if (hex.startsWith('0x')) hex = hex.slice(2);

  if (hex.length % 2 === 1) hex = '0' + hex;

  if (!isHex(hex)) throw new Error('invalid hex string in script');

  if (typeof VARIANT === 'undefined' || VARIANT === 'browser') {
    // charCodeAt + a nibble table, never substr: taking substrings of a
    // concatenation-built string forces a rope flatten, and JavaScriptCore
    // (Safari, every iOS WKWebView) re-flattens on EVERY call instead of
    // caching the flat result like V8 does — turning the old
    // parseInt(substr(...)) loop quadratic. 190 KB of payload took ~24s
    // under JSC and 4 ms under V8 with the previous implementation; this
    // form is linear on both.
    const length = hex.length >>> 1;
    const arr = new Uint8Array(length);
    for (let i = 0; i < length; ++i) {
      const hi = NIBBLES[hex.charCodeAt(i * 2) & 0x7f];
      const lo = NIBBLES[hex.charCodeAt(i * 2 + 1) & 0x7f];
      // unreachable after isHex() above, but kept so a future caller that
      // skips the pre-check still cannot produce silent garbage
      if (hi === 255 || lo === 255) throw new Error('bad hex char');
      arr[i] = (hi << 4) | lo;
    }
    return arr;
  } else {
    return Buffer.from(hex, 'hex');
  }
}

export default decodeHex;
